import AppKit
import SwiftUI

/// The small logo shown beside each connector in the Connections tab: Bump's app icon (embedded, 96 px), Gmail's envelope drawn from its
/// outline, and Messages' green bubble. Anything else gets a plain link symbol.
enum ConnectorIcon {
    /// Bump's app icon, 96 x 96 PNG.
    static let bumpPNG = ""

    /// Gmail's envelope mark (24 x 24 units).
    static let gmailPath = "M24 5.457v13.909c0 .904-.732 1.636-1.636 1.636h-3.819V11.73L12 16.64l-6.545-4.91v9.273H1.636A1.636 1.636 0 0 1 0 19.366V5.457c0-2.023 2.309-3.178 3.927-1.964L5.455 4.64 12 9.548l6.545-4.91 1.528-1.145C21.69 2.28 24 3.434 24 5.457z"

    static let bump: NSImage? = Data(base64Encoded: ConnectorIcon.bumpPNG).flatMap { NSImage(data: $0) }
}

struct ConnectorIconView: View {
    let id: String
    var size: CGFloat = 30

    var body: some View {
        Group {
            if self.id == "bump", let image = ConnectorIcon.bump {
                Image(nsImage: image).resizable().interpolation(.high).scaledToFit()
            } else if self.id.hasPrefix("gmail:") {
                ZStack {
                    RoundedRectangle(cornerRadius: self.size * 0.24, style: .continuous).fill(Color.white)
                    SVGPathShape(d: ConnectorIcon.gmailPath)
                        .fill(Color(red: 0.92, green: 0.26, blue: 0.21))
                        .frame(width: self.size * 0.62, height: self.size * 0.62)
                }
            } else if self.id == "messages" {
                ZStack {
                    RoundedRectangle(cornerRadius: self.size * 0.24, style: .continuous)
                        .fill(LinearGradient(colors: [Color(red: 0.37, green: 0.9, blue: 0.4), Color(red: 0.05, green: 0.75, blue: 0.2)], startPoint: .top, endPoint: .bottom))
                    Image(systemName: "message.fill").font(.system(size: self.size * 0.5)).foregroundStyle(.white)
                }
            } else {
                ZStack {
                    RoundedRectangle(cornerRadius: self.size * 0.24, style: .continuous).fill(Color.white.opacity(0.12))
                    Image(systemName: "link").font(.system(size: self.size * 0.45)).foregroundStyle(.white.opacity(0.7))
                }
            }
        }
        .frame(width: self.size, height: self.size)
        .clipShape(RoundedRectangle(cornerRadius: self.size * 0.24, style: .continuous))
    }
}
